class ControlBus(private val scope: CoroutineScope) {
    private val commands = MutableSharedFlow<ControlCommand>(extraBufferCapacity = 64)
    val state = MutableStateFlow(ComponentState.RUNNING)

    fun send(cmd: ControlCommand): Boolean = commands.tryEmit(cmd)

    fun start(handler: suspend (ControlCommand) -> Unit) = scope.launch {
        commands.collect { cmd ->                       // channel closes when the scope is cancelled
            handler(cmd)
        }
    }
}
// stop: scope.coroutineContext.cancelChildren()  -> collectors finish, channels close, state updated

