interface RouteControlMBean {
    val status: String                       // read-only attribute
    fun suspend(reason: String)              // command
    fun resume()
}

class RouteControl(private val route: Route) : RouteControlMBean {
    override val status: String get() = route.state.name
    override fun suspend(reason: String) { route.suspend(reason) }
    override fun resume() { route.resume() }
}

ManagementFactory.getPlatformMBeanServer().registerMBean(
    StandardMBean(RouteControl(route), RouteControlMBean::class.java),
    ObjectName("app.routes:type=Route,name=orders"))
